await app.register(rateLimit, { max: 120, timeWindow: '1 minute' });
const authAttemptWindowMs = 15 * 60 * 1000;
const authAttempts = new Map<string, { count: number; resetAt: number }>();
function authAccountKey(req:any, scope:string){
  const body=(req.body && typeof req.body==='object') ? req.body as any : {};
  const email=typeof body.email==='string' ? body.email.trim().toLowerCase() : '';
  return `${scope}:${email || String(req.ip || 'unknown')}`;
}
function authLimit(req:any, reply:any, scope:string){
  const key=authAccountKey(req,scope), now=Date.now();
  const current=authAttempts.get(key);
  if(!current || current.resetAt<=now){ authAttempts.set(key,{count:1,resetAt:now+authAttemptWindowMs}); return true; }
  if(current.count>=5){ reply.header('Retry-After',Math.ceil((current.resetAt-now)/1000)); err(reply,429,'too_many_requests','Too many authentication attempts. Try again later.'); return false; }
  current.count++; return true;
}
function clearAuthAttempts(req:any, scope:string){ authAttempts.delete(authAccountKey(req,scope)); }
const id = () => crypto.randomUUID();
const token = () => crypto.randomBytes(32).toString('base64url');
const hash = (s:string) => crypto.createHash('sha256').update(s).digest('hex');
function err(reply:any, status:number, code:string, message:string, fields?:unknown){ return reply.code(status).send({error:{code,message, ...(fields?{fields}: {})}}); }
const OWNER_PERMISSIONS=['dashboard:read','products:read','products:write','collections:write','inventory:write','media:write','orders:read','orders:write','orders:refund','customers:read','content:write','discounts:write','reviews:moderate','inquiries:respond','analytics:read','settings:write','staff:manage'];
async function permissionsForStaff(staff:any){
  if(String(staff.role)==='owner') return OWNER_PERMISSIONS;
  const r=await pool.query('SELECT permission FROM role_permissions WHERE role_id=$1 ORDER BY permission',[String(staff.role)]);
  return r.rows.map((x:any)=>x.permission);
}
function adminPermission(req:any){
  const path=String(req.url||'').split('?')[0].replace('/v1/','');
  const method=String(req.method||'GET');
  if(path==='admin/search') return null;
  if(path==='admin/dashboard') return 'dashboard:read';
  if(path==='admin/analytics') return 'analytics:read';
  if(path==='admin/customers' || path.startsWith('admin/customers/')) return 'customers:read';
  if(path==='admin/products' || path.startsWith('admin/products/')) return ['GET','HEAD'].includes(method)?'products:read':'products:write';
  if(path==='admin/inventory') return method==='GET'?'products:read':'inventory:write';
  if(path==='admin/collections' || path.startsWith('admin/collections/') || path==='admin/product-types' || path.startsWith('admin/product-types/')) return method==='GET'?'products:read':'collections:write';
  if(path==='admin/media' || path.startsWith('admin/media/')) return method==='GET'?'products:read':'media:write';
  if(path==='admin/orders' || path.startsWith('admin/orders/')) { if(method==='GET') return 'orders:read'; if(path.endsWith('/refunds')) return 'orders:refund'; if(path.endsWith('/notes')) return 'orders:read'; return 'orders:write'; }
  if(path.startsWith('admin/content/') || path.startsWith('admin/pages')) return 'content:write';
  if(path==='admin/discounts' || path.startsWith('admin/discounts/')) return 'discounts:write';
  if(path==='admin/reviews' || path.startsWith('admin/reviews/')) return 'reviews:moderate';
  if(path==='admin/inquiries' || path.startsWith('admin/inquiries/')) return 'inquiries:respond';
  if(path.startsWith('admin/settings/')) return 'settings:write';
  if(path==='admin/staff' || path.startsWith('admin/staff/') || path==='admin/roles' || path.startsWith('admin/roles/')) return 'staff:manage';
  return null;
}
async function session(req:any, kind:'customer'|'admin'){ const raw=req.cookies[kind==='admin'?'qp_admin':'qp_customer']; if(!raw) return null; const r=await pool.query('SELECT * FROM sessions WHERE id=$1 AND kind=$2 AND expires_at>now()',[raw,kind]); return r.rows[0]||null; }
async function requireSession(req:any, reply:any, kind:'customer'|'admin'){ const s=await session(req,kind); if(!s) { err(reply,401,'unauthorized','Authentication required'); return null; } return s; }
app.addHook('preHandler',async(req:any,reply)=>{
  const path=String(req.url||'').split('?')[0];
  if(!path.startsWith('/v1/admin/') || path.startsWith('/v1/admin/auth/')) return;
  const s=await session(req,'admin');
  if(!s){ err(reply,401,'unauthorized','Authentication required'); return reply; }
  const staff=(await pool.query('SELECT id,name,email,role,status FROM staff WHERE id=$1',[s.subject_id])).rows[0];
  if(!staff || staff.status!=='active'){ err(reply,401,'unauthorized','Authentication required'); return reply; }
  const permissions=await permissionsForStaff(staff);
  req.adminStaff=staff; req.adminPermissions=permissions;
  const required=adminPermission(req);
  if(required && !permissions.includes(required)){ err(reply,403,'forbidden','You do not have permission for this action'); return reply; }
});
async function product(r:any){
  const [cr,mr,vr,rr]=await Promise.all([
    pool.query('SELECT collection_id FROM product_collections WHERE product_id=$1 ORDER BY position',[r.id]),
    pool.query('SELECT m.* FROM media m JOIN product_media pm ON pm.media_id=m.id WHERE pm.product_id=$1 ORDER BY pm.position',[r.id]),
    pool.query('SELECT * FROM product_variants WHERE product_id=$1 ORDER BY position,created_at',[r.id]),
    pool.query("SELECT coalesce(avg(rating),0)::numeric average,count(*)::int count FROM reviews WHERE product_id=$1 AND status='approved'",[r.id])
  ]);
  const variants=(vr.rows.length?vr.rows:[{id:r.id,product_id:r.id,sku:r.sku||r.handle,title:'Default',options:{},price_kobo:r.price_kobo,compare_at_kobo:r.compare_at_kobo,stock:r.stock,policy:'deny',low_stock_threshold:5,media_id:null,position:0}]).map((v:any)=>({id:v.id,productId:r.id,sku:v.sku||r.handle,title:v.title,options:v.options||{},price:Number(v.price_kobo),compareAtPrice:v.compare_at_kobo==null?null:Number(v.compare_at_kobo),availability:Number(v.stock)>0?(Number(v.stock)<Number(v.low_stock_threshold||5)?'low_stock':'in_stock'):'out_of_stock',inventory:{tracked:true,available:Number(v.stock),policy:v.policy||'deny',lowStockThreshold:Number(v.low_stock_threshold||5)},mediaId:v.media_id||null,position:Number(v.position||0)}));
  const prices=variants.map((v:any)=>v.price), compares=variants.map((v:any)=>v.compareAtPrice).filter((x:any)=>x!==null);
  return {id:r.id,handle:r.handle,title:r.title,subtitle:r.subtitle,description:r.description,status:r.status,collectionIds:cr.rows.map((x:any)=>x.collection_id),media:mr.rows.map(mediaView),options:[],variants,priceRange:{min:Math.min(...prices),max:Math.max(...prices)},compareAtPriceRange:compares.length?{min:Math.min(...compares),max:Math.max(...compares)}:null,availability:variants.some((v:any)=>v.availability==='in_stock')?'in_stock':variants.some((v:any)=>v.availability==='low_stock')?'low_stock':'out_of_stock',productTypeId:r.product_type_id||null,attributes:r.attributes||{},video:r.video_url?{url:r.video_url,poster:null}:null,tags:r.tags||[],rating:{average:Number(rr.rows[0]?.average||0),count:Number(rr.rows[0]?.count||0)},featured:r.featured,seo:r.seo||{},createdAt:r.created_at,updatedAt:r.updated_at};
}
