const adminSessionView=async(r:any)=>{const roleId=String(r.role||'owner');const permissions=await permissionsForStaff(r);const roleRow=(await pool.query('SELECT id,name,description,system FROM roles WHERE id=$1',[roleId])).rows[0];const role={id:roleId,name:roleRow?.name||roleId,description:roleRow?.description||'',permissions,system:Boolean(roleRow?.system||roleId==='owner')};const staff={id:r.id,name:r.name,email:r.email,roleId,status:r.status||'active',lastActiveAt:null};return {staff,role,permissions,expiresAt:new Date(Date.now()+604800000).toISOString()};};
async function login(req:any,reply:any,kind:'admin'|'customer'){if(!authLimit(req,reply,`${kind}:login`))return;const s=z.object({email:z.string().email(),password:z.string().min(8)}).safeParse(req.body);if(!s.success)return err(reply,400,'validation_error','Invalid credentials');const table=kind==='admin'?'staff':'customers';const r=await pool.query(`SELECT * FROM ${table} WHERE email=$1 AND ${kind==='admin'?"status='active'":"true"}`,[s.data.email.toLowerCase()]);if(!r.rowCount||!(await argon2.verify(r.rows[0].password_hash,s.data.password)))return err(reply,401,'invalid_credentials','Invalid credentials');clearAuthAttempts(req,`${kind}:login`);const raw=token();await pool.query('INSERT INTO sessions(id,subject_id,kind,expires_at) VALUES($1,$2,$3,now()+interval \'7 days\')',[raw,r.rows[0].id,kind]);reply.setCookie(kind==='admin'?'qp_admin':'qp_customer',raw,{httpOnly:true,secure:true,sameSite:'lax',path:'/',maxAge:604800});return kind==='admin'?await adminSessionView(r.rows[0]):{customer:{id:r.rows[0].id,name:r.rows[0].name,email:r.rows[0].email}};}
