app.put('/v1/customers/me/wishlist',async(req,reply)=>{const s=await requireSession(req,reply,'customer');if(!s)return;const body=z.object({productIds:z.array(z.string().uuid()).max(200)}).safeParse(req.body);if(!body.success)return err(reply,400,'validation_error','Invalid wishlist');await pool.query('INSERT INTO wishlists(customer_id,product_ids) VALUES($1,$2) ON CONFLICT(customer_id) DO UPDATE SET product_ids=EXCLUDED.product_ids,updated_at=now()',[s.subject_id,JSON.stringify(body.data.productIds)]);return {items:body.data.productIds};});
